use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let year = input["input"][0].as_i64().unwrap();
    let month = input["input"][1].as_i64().unwrap();
    let day = input["input"][2].as_i64().unwrap();
    let mut days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    if month == 2 {
        if (year % 4 == 0 && year % 100 != 0) || year % 400 == 0 {
            days_in_month[1] = 29;
        }
    }
    Value::from(days_in_month[month as usize] - day as i64 + 1)
}
